insert into public.concerts (wp_id, slug, title, description, video_type, video_url, video_id, thumbnail_url, duration, release_date, original_link, composers, instruments, periods, nationalities, qualities, performers, categories, audio_tracks, published)
values
  (1225, 'piano-quartet-in-a-minor', 'Piano Quartet in A minor', 'Gustav Mahler''s Piano Quartet in A minor is the sole surviving piece of instrumental chamber music by the great Austrian symphonist. He composed it in 1876, when he was only fifteen or sixteen and in his first year at the Vienna Conservatory. It survives as a single completed movement in sonata form, marked Nicht zu schnell (not too fast), followed by a brief fragment of an unfinished scherzo. Written under teachers steeped in the Brahmsian tradition, the movement is a brooding, impassioned work whose sweeping Romantic gestures already hint at the emotional intensity of Mahler''s later symphonies. Mahler (1860-1911) went on to become one of the most influential composers and conductors of his era, though he abandoned instrumental chamber music after these student years.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/fc098347-380b-44f3-a430-503c50b2c38e/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/2022/01/IMG_1280.jpg', '13 min 23 sec', '12/05/2021', 'https://play.creartbox.nyc/title/piano-quartet-in-a-minor/', ARRAY['Gustav Mahler']::text[], ARRAY['Cello','Piano','Viola','Violin']::text[], ARRAY['19th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Josefina Urraca, piano','Keir GoGwilt, violin','Matthew Cohen, viola','Yi Qun Xu, cello']::text[], ARRAY[]::text[], '[]'::jsonb, false),
  (1240, 'prelude-recitatif-et-variations', 'Prelude Recitatif et variations', 'Maurice Durufle''s Prelude, recitatif et variations, Op. 3, composed in 1928, is a jewel of the French chamber repertoire written for the unusual trio of flute, viola and piano. As its title promises, the work unfolds in three linked sections: a pensive, shadowed Prelude, a freely declaimed Recitatif, and a closing theme with variations of increasing warmth and brilliance. The writing is refined, modal and gently impressionistic, prizing atmosphere over display. Durufle (1902-1986) was a French composer and organist known for his exacting self-criticism; he published only a handful of works and continued to revise many for years. Though celebrated above all for his Requiem, this early trio reveals the same luminous craftsmanship and love of long, singing lines.', 'youtube', '8yoCg0Hfb54', '8yoCg0Hfb54', 'https://play.creartbox.nyc/wp-content/uploads/2022/01/09.jpg', '10 min 54 sec', '08/11/2013', 'https://play.creartbox.nyc/title/prelude-recitatif-et-variations/', ARRAY['Maurice Durufle']::text[], ARRAY['Flute','Piano','Viola']::text[], ARRAY['20th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Guillermo Laporta, flute','Josefina Urraca, piano','Nathan Schram, viola']::text[], ARRAY[]::text[], '[]'::jsonb, false),
  (1282, 'second-violin-chaconne', 'Second Violin Chaconne', 'This is the celebrated Chaconne, the towering final movement of Johann Sebastian Bach''s Partita No. 2 in D minor for solo violin, BWV 1004, composed around 1717-1720 as part of his cycle of Sonatas and Partitas for unaccompanied violin. Built on a repeating harmonic pattern, the Chaconne spins dozens of variations from a simple sarabande-like bass, journeying from D minor through a radiant central section in D major and back, all on a single instrument. Brahms wrote to Clara Schumann that on one stave, for a small instrument, Bach writes a whole world of the deepest thoughts and most powerful feelings. It stands among the greatest works ever written for the violin and a summit of the Baroque.', 'vimeo', '537780913', '537780913', 'https://play.creartbox.nyc/wp-content/uploads/Screen-Shot-2022-01-29-at-2.05.46-PM-scaled.jpg', '14 min 33 sec', '05/15/2021', '', ARRAY['J.S. Bach']::text[], ARRAY['Violin']::text[], ARRAY['18th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Mari Lee, violin']::text[], ARRAY[]::text[], '[]'::jsonb, false),
  (1284, 'sonata-kv-283-ii-mov', 'Sonata KV.283 II mov', 'The Andante is the tender central movement of Mozart''s Piano Sonata No. 5 in G major, K. 283, one of the six early keyboard sonatas (K. 279-284) he composed during a stay in Munich around 1774-75, at the time of the premiere of his opera La finta giardiniera. Cast in a songful C major, the movement pairs a graceful, aria-like melody with delicate accompaniment, its poise and clarity anticipating the operatic lyricism of the mature composer. The set shows the not-yet-nineteen-year-old Mozart mastering the Classical sonata style with effortless charm. Wolfgang Amadeus Mozart (1756-1791) remains one of the central figures of the Classical era, and these Munich sonatas count among the earliest of his solo keyboard works to enter the standard repertoire.', 'vimeo', '537812370', '537812370', 'https://play.creartbox.nyc/wp-content/uploads/2022/01/Screen-Shot-2022-01-15-at-9.27.45-AM.jpg', '6 min 25 sec', '05/15/2021', '', ARRAY['Mozart']::text[], ARRAY['Piano']::text[], ARRAY['18th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Josefina Urraca, piano','Sarah K. Williams, visual Artist']::text[], ARRAY[]::text[], '[]'::jsonb, false),
  (1287, 'third-suite-for-solo-cello', 'Third Suite for solo cello', 'Benjamin Britten composed his Suite for Cello No. 3, Op. 87, in 1971 for his friend Mstislav Rostropovich, whose playing of Bach''s unaccompanied suites had inspired the whole series. The work draws on Britten''s deep affection for Russia: it weaves together four Russian melodies - three folk songs arranged by Tchaikovsky and the Orthodox hymn Kontakion for the Departed - which finally emerge in full in a long closing Passacaglia that lasts nearly as long as everything before it. Political restrictions delayed Rostropovich''s premiere until December 1974, at the Snape Maltings. Elegiac and searching, it is among the most personal of Britten''s late works. Britten (1913-1976) was the leading English composer of his generation. This CreArtBox presentation pairs the music with dance.', 'vimeo', '542211232', '542211232', 'https://play.creartbox.nyc/wp-content/uploads/2022/01/britten.jpg', '4 min 15 sec', '05/11/2021', '', ARRAY['Benjamin Britten']::text[], ARRAY['Cello','Dance']::text[], ARRAY['20th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Hsiao-Chu Hsia, dancer','Julia Yang, cello']::text[], ARRAY[]::text[], '[]'::jsonb, false),
  (1291, 'quartet-twv-43-g4', 'Quartet TWV 43 g4', 'Georg Philipp Telemann''s Quartet in G major, TWV 43:G4, comes from his famous Paris Quartets - two sets of chamber works for flute, violin, viola da gamba (or cello) and continuo that count among the finest instrumental music of the late Baroque. The G major quartet belongs to the Nouveaux quatuors en six suites, published in Paris in 1738 after the acclaim Telemann''s earlier quartets had won there. He called such pieces ''quadros,'' treating the upper voices in flexible, often equal dialogue that blends French elegance with Italian brilliance. Largely self-taught, Telemann (1681-1767) became a composer against his family''s wishes and grew into one of the most prolific and admired musicians of his age. CreArtBox performs this version with an expanded ensemble.', 'vimeo', '671506323', '671506323', 'https://play.creartbox.nyc/wp-content/uploads/2022/01/003-2.jpg', '7 min 22 sec', '12/05/2021', '', ARRAY['G. P. Telemann']::text[], ARRAY['Cello','Flute','Piano','Viola','Violin']::text[], ARRAY['18th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Guillermo Laporta, flute','Josefina Urraca, piano','Keir GoGwilt, violin','Matthew Cohen, viola','Yi Qun Xu, cello']::text[], ARRAY[]::text[], '[]'::jsonb, false),
  (1301, 'luciform', 'Luciform', 'Luciform (2011, revised 2013) is a concerto for solo flute and electronics by the American composer and performer Mario Diaz de Leon. It forms part 4 of his Mansion Cycle (2009-2011) and the third work in Cosmology, an ongoing series for solo performer and electronics. The title fuses the Latin lux (light) with ''form'' - a light-form evoking Lucifer as light-bearer and morning star - and the music charts a journey inward through shifting vision-states, hovering between diabolical intensity and lucid clarity. Diaz de Leon''s output spans modern classical music, experimental electronics, extreme metal and improvisation, and here the flute is driven to virtuosic extremes against a churning electronic backdrop. The piece was written for and premiered by flutist Claire Chase.', 'vimeo', '', '', 'https://play.creartbox.nyc/wp-content/uploads/IMG_1065.jpg', '', '12/02/2021', '', ARRAY['M. Diaz de Leon']::text[], ARRAY['Flute']::text[], ARRAY['21st Century']::text[], ARRAY['American']::text[], ARRAY['HD video']::text[], ARRAY['Guillermo Laporta, flute','Marieken Cochius, painter']::text[], ARRAY[]::text[], '[]'::jsonb, false),
  (1428, 'just-as-they-are', 'Just As They Are', 'Just As They Are (2015) is a roughly five-minute work for amplified quintet - flute, clarinet, violin, cello and piano - with pre-recorded audio, by the British composer Anna Clyne. CreArtBox performed it as part of the first edition of the CreArt Music Festival. A GRAMMY-nominated composer of acoustic and electro-acoustic music, Clyne (born in London in 1980) has been described in a New York Times profile as a ''composer of uncommon gifts and unusual methods'' and by NPR as ''fearless,'' and ranks among the most performed composers of her generation. Long based in the United States, she has held residencies with major orchestras including the Chicago Symphony. Her music often layers live instruments with electronic and recorded sound, as it does here.', 'audio', 'https://play.creartbox.nyc/wp-content/uploads/Just-as-they-are.mp3', '', 'https://play.creartbox.nyc/wp-content/uploads/030-1.jpg', '5 in 23 sec', '', '', ARRAY['Anna Clyne']::text[], ARRAY['Cello','Clarinet','Electronics','Flute','Piano']::text[], ARRAY['21st Century']::text[], ARRAY['European']::text[], ARRAY['Lossless audio']::text[], ARRAY['Guillermo Laporta, flute','Johnna Wu, violin','Josefina Urraca, piano','Julia Yang, cello','Nicholas Gallas, clarinet']::text[], ARRAY[]::text[], '[{"title":"Just As They Are","url":"https://play.creartbox.nyc/wp-content/uploads/Just-as-they-are.mp3"}]'::jsonb, false),
  (1449, 'coming-together', 'Coming Together', 'Frederic Rzewski''s Coming Together (1971) is a landmark of American minimalism. Over a driving, relentlessly additive bass line of steady sixteenth notes - the only fully notated part, from which the other players derive their material - a narrator recites, a few words at a time, a letter written by Sam Melville, an inmate killed in the 1971 Attica prison uprising. Scored for open instrumentation (here a narrator with flute, clarinet, violin, cello, piano and electronics), the piece builds hypnotic momentum into a politically charged meditation on isolation, resolve and the endurance of the human spirit. Rzewski (1938-2021) was an American composer and virtuoso pianist whose music frequently engaged political themes, most famously in his piano variations The People United Will Never Be Defeated!', 'audio', '', '', 'https://play.creartbox.nyc/wp-content/uploads/004-1.jpg', '12 min 22 sec', '05/21/2014', '', ARRAY['Frederic Rzewski']::text[], ARRAY['Actor','Cello','Clarinet','Electronics','Flute','Piano','Violin']::text[], ARRAY['20th Century']::text[], ARRAY['American']::text[], ARRAY['Lossless audio']::text[], ARRAY['Doori Na, violin','Guillermo Laporta, flute','Josefina Urraca, piano','Rick Cekovsky, actor','Tagore Gonzalez, clarinet','Yves Dharamraj, cello']::text[], ARRAY[]::text[], '[{"title":"Coming Together","url":"https://play.creartbox.nyc/wp-content/uploads/Coming-Together-Live.wav"}]'::jsonb, false),
  (1472, 'the-old-castle', 'The Old Castle', '"The Old Castle" (Il vecchio castello) is the second picture in Modest Mussorgsky''s Pictures at an Exhibition, the suite of piano pieces he composed in 1874 as a musical tour of a memorial exhibition for his friend, the artist and architect Viktor Hartmann. Inspired by a Hartmann watercolor, the movement evokes a medieval castle before which a troubadour sings a melancholy song, its long-breathed melody unfolding over a steady drone. Maurice Ravel''s celebrated 1922 orchestration famously gives the tune to the alto saxophone. Mussorgsky, a leading voice of the Russian nationalist "Mighty Handful," prized vivid pictorial character over polish. CreArtBox performs the movement here in a chamber arrangement.', 'vimeo', '667030044', '667030044', 'https://play.creartbox.nyc/wp-content/uploads/18.jpg', '4 min 42 sec', '08/11/2013', '', ARRAY['Modest Mussorgsky']::text[], ARRAY['Cello','Dance','Piano','Viola']::text[], ARRAY['19th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Josefina Urraca, piano','Nathan Schram, viola','Yung-Li Chen, dancer','Yves Dharamraj, cello']::text[], ARRAY[]::text[], '[]'::jsonb, false),
  (1474, 'eclipse', 'Eclipse', '"Eclipse" began life as the overture to Noctum, a chamber opera the Spanish composer Marcos Fernandez-Barrero wrote during his 2011 residency with the Cre.Art Project. The overture preludes a story full of magic and fantasy where dreams and reality meet, and its success across many performances in the United States and Spain later encouraged the composer to develop the material further, including an orchestral version, Eclipse para orquesta (2016). Born in Barcelona in 1984, Fernandez-Barrero is a pianist and composer whose output spans concert works, opera, dance and film music. This CreArtBox version is scored for flute, viola, cello and piano.', 'vimeo', '667029352', '667029352', 'https://play.creartbox.nyc/wp-content/uploads/07.jpg', '', '08/11/2013', '', ARRAY['Marcos Fernandez']::text[], ARRAY['Cello','Flute','Piano','Viola']::text[], ARRAY['21st Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Guillermo Laporta, flute','Josefina Urraca, piano','Nathan Schram, viola','Yves Dharamraj, cello']::text[], ARRAY[]::text[], '[]'::jsonb, false),
  (524, 'spiegel-im-spiegel', 'Spiegel im Spiegel', 'Spiegel im Spiegel ("mirror in the mirror") is a meditative work by the Estonian composer Arvo Part, written in 1978, shortly before he emigrated from the Soviet Union. It is one of the purest examples of his tintinnabuli style: a slowly rising and falling melodic voice unfolds over serene, bell-like arpeggiations of a single tonic triad, following so strict a formula that no note is left to chance. The title evokes an infinite regress of reflections, mirrors facing mirrors. Originally for violin and piano, it has been recast for many instruments and is heard here in a version for violin and piano. Part remains among the most performed living composers, celebrated for music of luminous stillness and spiritual depth.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/b87968d6-f21b-4f09-a673-531c1903dcfc/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/2021/08/IMG_1240-scaled.jpg', '9 min 23 sec', '12/04/2021', 'https://play.creartbox.nyc/title/grand-tour/', ARRAY['Arvo Pärt']::text[], ARRAY['Dance','Piano','Violin']::text[], ARRAY['20th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Josefina Urraca, piano','Keir GoGwilt, violin','Mary Taylor Hennings, dancer','Yi Qun Xu, cello']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (702, '12-queens-preludes', '12 Queens Preludes', '12 Queens Preludes is an evening-length cycle for flute and piano by Guillermo Laporta, the Spanish flutist-composer who co-founded CreArtBox in New York with pianist Josefina Urraca. Composed in 2020 and running some forty-four minutes, it reimagines the prelude - traditionally a brief piece that ushers in something greater - as a meditation on life itself as "an endless prelude," where meaning becomes clear only once larger events arrive. Across its movements the music turns flashes of remembering the past into sound: trust and vertigo, uncertainty and assurance, ambiguity and remembrance. Laporta (flute) and Urraca (piano) perform it here, in the pairing for which it was written.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/548596d7-a8ab-4c8e-84ea-bd2e1a028285/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/DSC00857.jpg', '44 min 15 sec', '10/16/2021', 'https://play.creartbox.nyc/title/queens-preludes/', ARRAY['Guillermo Laporta']::text[], ARRAY['Flute','Piano']::text[], ARRAY['21st Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Guillermo Laporta, flute','Josefina Urraca, piano']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (1257, 'mandalas-in-the-rubble', 'Mandalas in the Rubble', 'Mandalas in the Rubble is a chamber work by the Chinese-born, US-based composer Dai Wei, written after a journey through Nepal and Tibet. She was struck by how the 2015 earthquake reduced many of the Kathmandu Valley''s historic temples to debris, yet left their concentric, mandala-shaped bases intact. The piece imagines a woman''s mourning ritual after the loss of her husband: strings are partly detuned to lend a "ramshackle and dark" color, and a free-flowing, sporadic texture gradually gathers into a peaceful, non-violent wholeness - an image of shattered things reshaping themselves into strength and beauty. Dai Wei, also an experimental Khoomei throat singer, writes music that moves between East and West, acoustic and electronic.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/ca51ef42-2e34-4fc6-be69-e01f96bbfc32/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/2022/01/004.jpg', '7 min 59 sec', '08/31/2019', 'https://play.creartbox.nyc/title/mandalas-in-the-rubble', ARRAY['Dai Wei']::text[], ARRAY['Cello','Clarinet','Piano','Violin']::text[], ARRAY['21st Century']::text[], ARRAY['American']::text[], ARRAY['Lossless audio']::text[], ARRAY['Jonathan Cohen, clarinet','Josefina Urraca, piano','Julia Yang, cello','Mari Lee, violin']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (1289, 'legende', 'Legende', 'Legende (d''apres Les Elfes de Leconte de Lisle) is one of the cornerstones - and one of the most demanding pieces - of the solo harp repertoire. The French harpist-composer Henriette Renie (1875-1956) wrote it in 1901, at the age of twenty-six, and it was first performed the following year. A programmatic work, it draws on "Les Elfes," a ballad by the Parnassian poet Leconte de Lisle (1818-1894) in which a knight riding to his wedding is lured to his death by elves. Renie dedicated the piece to her teacher, the Paris Conservatoire harp professor Alphonse Hasselmans. A virtuoso admired across Europe, Renie greatly expanded the expressive and technical range of her instrument and inspired later composers to write idiomatically for the harp.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/64de021c-2d12-4318-b21b-7ee6851d53ee/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/2022/01/Screen-Shot-2022-01-15-at-9.34.18-AM-scaled.jpg', '10 min 49 sec', '12/05/2021', '', ARRAY['Henriette Renie']::text[], ARRAY['Harp']::text[], ARRAY['20th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Jane Yoon, harp']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (1293, 'petite-suite', 'Petite Suite', 'Andre Jolivet''s Petite Suite for flute, viola and harp grew out of incidental music he wrote in the early 1940s for a staging of Lope de Vega''s play Aimer sans savoir qui, directed by Jean Vilar. Jolivet drew the concert suite from that theatre score and left brief notes picturing the stage action its movements once accompanied. Cast in several short movements, the music shows the transparent, luminous side of a composer who, with Messiaen and others, founded the group La Jeune France in 1936, seeking to restore "magic" and human feeling to modern music. Where his best-known works can be incantatory and fierce, the Petite Suite is intimate and finely colored, its flute, viola and harp interweaving with Gallic clarity.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/9aab96b2-bdda-4546-8470-e4754e8d6935/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/IMG_1046-1.jpg', '4 min 49 sec', '12/02/2021', '', ARRAY['Andre Jolivet']::text[], ARRAY['Flute','Harp','Viola']::text[], ARRAY['20th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Guillermo Laporta, flute','Jane Yoon, harp','Matthew Cohen, viola']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (1326, 'fourth-symphony', 'Fourth Symphony', 'Gustav Mahler composed his Symphony No. 4 in G major in 1899-1900, building it around a song, "Das himmlische Leben," that he had written in 1892. That song - a child''s beaming vision of heaven - crowns the finale, sung by a solo soprano. More modest in scale and gentler in tone than the vast symphonies around it, the Fourth calls for a comparatively restrained orchestra and unfolds with an almost classical grace shaded by irony: sleigh bells, folk-like tunes and a serene slow movement lead to that heavenly close. Mahler, the Bohemian-born Austrian conductor and composer who bridged late Romanticism and modernism, premiered the work in Munich in 1901. CreArtBox performs it in a chamber-orchestra arrangement.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/eedb7a24-f2b4-44ef-932a-ad8d11633aaf/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/19.jpg', '58 min 15 sec', '03/30/2018', '', ARRAY['Gustav Mahler']::text[], ARRAY['Chamber orchestra']::text[], ARRAY['20th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['CreArtBox Ensemble','Le Train Bleu Ensemble','Ranson Wilson, conductor']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (1330, 'piano-trio-no-1-op-49', 'Piano Trio No.1, Op.49', 'Felix Mendelssohn composed his Piano Trio No. 1 in D minor, Op. 49, in 1839, and it was hailed at once as a masterpiece; reviewing it, Robert Schumann called Mendelssohn "the Mozart of the nineteenth century." Impassioned and richly lyrical, it opens with a surging cello-and-piano melody, followed by a songful Andante in the vein of his Songs Without Words, a fleet, gossamer scherzo, and a spirited finale. The work is scored for violin, cello and piano; in an 1840 exchange with Ignaz Moscheles, Mendelssohn discussed a London publisher''s request for a version replacing the violin with flute. CreArtBox performs the trio in that flute, cello and piano arrangement, which lends its familiar textures a brighter, airier color.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/ee1683d9-17df-4458-aa7f-443332cbe288/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/019.jpg', '6 min 53 sec', '03/30/2022', '', ARRAY['Felix Mendelssohn']::text[], ARRAY['Cello','Flute','Piano']::text[], ARRAY['19th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Guillermo Laporta, flute','Josefina Urraca, piano','Julia Yang, cello']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (1419, 'mariri', 'Mariri', 'Mariri is a chamber work for flute, clarinet, violin, cello, piano and electronics by the American composer Joshua Penman, written in 2016 and running roughly eleven minutes. CreArtBox commissioned it for Visuality, a music-and-theater production whose narrative drew on the psychology of Freud and Rogers. Penman, trained at Yale and the University of Michigan, writes music preoccupied with how sound can shift consciousness, an interest shaped by his study of Indian classical singing and of the Shipibo shamans'' healing icaros. His idiom blends acoustic instruments with electronics in a meditative, cinematic vein. This performance was recorded by CreArtBox in December 2016.', 'none', '', '', 'https://play.creartbox.nyc/wp-content/uploads/313.jpg', '11 min 33 sec', '12/03/2016', '', ARRAY['Joshua Penman']::text[], ARRAY['Cello','Clarinet','Electronics','Flute','Piano','Violin']::text[], ARRAY['21st Century']::text[], ARRAY['American']::text[], ARRAY['Lossless audio']::text[], ARRAY['Clara Vazquez, violin','Guillermo Laporta, flute','Josefina Urraca, piano','Mindi Asher, cello','Nicholas Gallas, clarinet']::text[], ARRAY[]::text[], '[{"title":"Mariri","url":"https://creartbox-media-cdn.b-cdn.net/webimg/audio/mariri.mp3"}]'::jsonb, true),
  (1420, 'petroushkates', 'Petroushskates', 'Petroushskates (1980) is a roughly six-minute chamber work for flute, clarinet, violin, cello and piano by the American composer Joan Tower, who wrote it as pianist and founding member of the Da Capo Chamber Players. The title fuses two images. One is Stravinsky''s Petrushka, whose bustling, colorful Shrovetide Fair scene mirrors the piece''s opening; the other is ice skating, whose curving, twirling, continuously flowing motion Tower admired while watching Olympic figure skaters. Together they conjure a ''carnival on ice,'' short flurries of notes twirling and leaping like skaters over a single unbroken line. Lively and witty, it has become one of Tower''s most frequently performed works.', 'audio', '', '', 'https://play.creartbox.nyc/wp-content/uploads/016.jpg', '6 min 10 sec', '03/13/2015', '', ARRAY['Joan Tower']::text[], ARRAY['Cello','Clarinet','Flute','Piano','Violin']::text[], ARRAY['20th Century']::text[], ARRAY['American']::text[], ARRAY['Lossless audio']::text[], ARRAY['Anton Rist, clarinet','Guillermo Laporta, flute','Josefina Urraca, piano','Keir GoGwilt, violin','Yves Dharamraj, cello']::text[], ARRAY[]::text[], '[{"title":"Petroushskates","url":"https://play.creartbox.nyc/wp-content/uploads/Petroushkates.mp3"}]'::jsonb, true),
  (1434, 'three-watercolors', 'Three watercolors', 'Trois Aquarelles (Three Watercolours) is a set of three pieces by the French flutist-composer Philippe Gaubert, completed in 1921. Despite the delicate title, these are fully developed movements rather than miniatures: Par un clair matin, cheerful and energetic; Soleil d''automne, gentle and touched with elegiac nostalgia; and a Serenade coloured by a Spanish or Basque lilt, evoking the region where Gaubert kept a summer home. Gaubert conceived the work for standard piano trio, violin, cello and piano, but sanctioned an equally effective version replacing the violin with flute, the instrument on which he was a celebrated virtuoso. CreArtBox performs it in that flute, cello and piano scoring.', 'vimeo', '666991022', '666991022', 'https://play.creartbox.nyc/wp-content/uploads/026.jpg', '8 min 38 sec', '03/30/2019', 'https://play.creartbox.nyc/title/three-watercolors/', ARRAY['Philippe Gaubert']::text[], ARRAY['Cello','Flute','Piano']::text[], ARRAY['20th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Guillermo Laporta, flute','Josefina Urraca, piano','Julia Yang, cello']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (1435, 'dawnlight', 'Dawnlight', 'Dawnlight is a chamber work for flute, clarinet, violin, cello, piano and electronics by the American composer Joshua Penman, written in 2017 and lasting about twelve and a half minutes; it was premiered by CreArtBox. A Yale and University of Michigan graduate who has also scored films and toured with his electroacoustic project Akara, Penman is drawn to music that alters consciousness and traces an inner journey of awareness. Here he joins live instruments with electronics in the meditative, luminous, cinematic idiom that runs through his concert work, the title itself suggesting first light breaking over darkness.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/c807cfac-3c2b-498b-950f-efecb34e73ca/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/005.jpg', '12 min 28 sec', '05/18/2017', 'https://play.creartbox.nyc/title/dawnlight/ ‎', ARRAY['Joshua Penman']::text[], ARRAY['Cello','Clarinet','Electronics','Flute','Piano','Violin']::text[], ARRAY['21st Century']::text[], ARRAY['American']::text[], ARRAY['HD video']::text[], ARRAY['Guillermo Laporta, flute','Johnna Wu, violin','Josefina Urraca, piano','Julia Yang, cello','Nicholas Gallas, clarinet']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (1441, 'sonata-in-b-minor', 'Sonata in B minor', 'The Violin Sonata in B minor, P. 110, completed in 1917, is one of Ottorino Respighi''s major chamber works, written in the same period as his celebrated Fontane di Roma. Cast in three movements, a broad opening Moderato, an Andante espressivo, and a closing Passacaglia of mounting intensity, it marries late-Romantic sweep with Respighi''s gift for orchestral color and long-breathed melody. The sonata was first performed in Naples in 1918 by violinist Arrigo Serato with pianist Alessandro Longo. Respighi, an Italian composer, conductor and scholar, is best remembered for his Roman orchestral tone poems. CreArtBox presents the sonata in an arrangement that gives the violin part to the flute.', 'audio', 'https://play.creartbox.nyc/wp-content/uploads/DuoH-Respighi_I-Edit1-161018.wav', '', 'https://play.creartbox.nyc/wp-content/uploads/CD100_out.jpg', '9 min 34 sec', '01/17/2016', '', ARRAY['Ottorino Respighi']::text[], ARRAY['Flute','Piano']::text[], ARRAY['20th Century']::text[], ARRAY['European']::text[], ARRAY['Lossless audio']::text[], ARRAY['Guillermo Laporta, flute','Josefina Urraca, piano']::text[], ARRAY[]::text[], '[{"title":"Sonata in B minor","url":"https://play.creartbox.nyc/wp-content/uploads/DuoH-Respighi_I-Edit1-161018.wav"}]'::jsonb, true),
  (1442, 'awave', 'Awave', 'Awave is a multimedia suite for flute, piano, electronics and video by Guillermo Laporta, the Spanish flutist-composer and co-founder of CreArtBox in New York. Composed in 2018-2019 and gathering nine original pieces, it draws on Laporta''s travels across Europe, weaving symphonic color, chamber intimacy, theatrical sound design and a film-score sensibility together with his own words and images. First presented by CreArtBox, the suite unfolds as a personal, cinematic travelogue in sound and image, moving between reflection and spectacle across its interlinked movements.', 'none', '', '', '', '', '', '', ARRAY['Guillermo Laporta']::text[], ARRAY[]::text[], ARRAY['21st Century']::text[], ARRAY['European']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '[]'::jsonb, false),
  (1446, 'noctum-concerto', 'Noctum Concerto', 'Noctum Concerto is a concerto for flute and clarinet with chamber ensemble and electronics by Marcos Fernandez, running about twelve minutes. It grows out of Noctum, the chamber opera Fernandez composed as resident composer of Cre.Art Project, the European forerunner of CreArtBox, a story of magic and fantasy in which dream and reality meet. Barcelona-born and based between Madrid, Barcelona and London, Fernandez trained as a pianist at ESMUC, studied composition at the Royal Conservatoire of Scotland and film-music composition at London''s Royal College of Music. He writes for projects where image and narrative call on music to complete the story, in an atmospheric, cinematic idiom.', 'none', '', '', 'https://play.creartbox.nyc/wp-content/uploads/013.jpg', '12 min 10 sec', '05/23/2014', '', ARRAY['Marcos Fernandez']::text[], ARRAY['Cello','Clarinet','Electronics','Flute','Piano','Violin']::text[], ARRAY['21st Century']::text[], ARRAY['European']::text[], ARRAY['Lossless audio']::text[], ARRAY['Doori Na, violin','Guillermo Laporta, flute','Josefina Urraca, piano','Tagore Gonzalez, clarinet','Yves Dharamraj, cello']::text[], ARRAY[]::text[], '[{"title":"Noctum Concerto for flute and clarinet","url":"https://play.creartbox.nyc/wp-content/uploads/Marcos-Fernandez-Flute-clarinet-concierto-remastered-2022.wav"}]'::jsonb, true),
  (1481, 'sonata-for-clarinet-flute-and-piano', 'Sonata for clarinet, flute and piano', 'Maurice Emmanuel (1862-1938) was a French composer and pioneering musicologist whose language drew on ancient Greek modes, folk song and the colors of Impressionism. His Sonate en trio, Op. 11 (1907), for flute, clarinet and piano, unfolds in three movements: a spirited Allegro con spirito built on a folk-like theme, a songful Adagio, and a featherlight closing Allegro molto e leggierissimo. Fresh, modal and transparent in texture, it is dedicated to the ethnomusicologists Raoul and Marguerite d''Harcourt and has become a favorite of the wind-chamber repertoire.', 'audio', 'https://play.creartbox.nyc/wp-content/uploads/3.EMMANUEL-3.wav', '', 'https://play.creartbox.nyc/wp-content/uploads/IMG_2667-scaled.jpg', '', '04/02/2011', '', ARRAY['Maurice Emmanuel']::text[], ARRAY['Clarinet','Flute','Piano']::text[], ARRAY['20th Century']::text[], ARRAY['European']::text[], ARRAY['Lossless audio']::text[], ARRAY['Guillermo Laporta, flute','Marcos Fernandez, piano','Tagore Gonzalez, clarinet']::text[], ARRAY[]::text[], '[{"title":"Sonata for clarinet, flute and piano","url":"https://play.creartbox.nyc/wp-content/uploads/3.EMMANUEL-3.wav"}]'::jsonb, false),
  (1484, 'petite-suite-2', 'Petite Suite', 'Claude Debussy''s Petite Suite, L. 65, was composed for piano four hands between 1886 and 1889 and first performed in Paris on 2 February 1889 by the composer with his publisher Jacques Durand. Its four movements, En bateau, Cortege, Menuet and Ballet, pair the elegance of the salon with the freshness of the young Debussy; the first two take their titles and mood from poems in Verlaine''s Fetes galantes. Widely arranged ever since, most famously for orchestra by Henri Busser, the suite is heard here in a version for flute, clarinet and piano. Debussy, the pivotal French composer of his age, would soon transform European music.', 'vimeo', '671492590', '671492590', 'https://play.creartbox.nyc/wp-content/uploads/deb.jpg', '14 min 07 sec', '09/01/2018', '', ARRAY['Claude Debussy']::text[], ARRAY['Clarinet','Flute','Piano']::text[], ARRAY['19th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Guillermo Laporta, flute','Jonathan Cohen, clarinet','Josefina Urraca, piano']::text[], ARRAY[]::text[], '[]'::jsonb, false),
  (1607, 'flashes-and-illuminations', 'Flashes and Illuminations', 'Flashes and Illuminations is a song cycle for baritone and piano by the American composer John Harbison, written in 1996 and commissioned by Reader''s Digest/Meet the Composer for baritone Sanford Sylvan and pianist David Breitman. Conceived to fall equally to singer and pianist, it gathers poems that invite sustained reflection, drawing its title in part from the "Flashes and Dedications" section of Eugenio Montale''s book La Bufera (The Storm). Harbison, a Pulitzer Prize- and MacArthur-winning composer long associated with Boston and MIT, is celebrated for vocal and operatic writing of unusual literary sensitivity, and this intimate cycle showcases his gift for setting text with clarity, wit, and emotional depth.', 'none', '', '', 'https://play.creartbox.nyc/wp-content/uploads/004-2.jpg', '3 min 51 sec', '05/15/2021', '', ARRAY['John Harbison']::text[], ARRAY['Voice']::text[], ARRAY['20th Century']::text[], ARRAY['American']::text[], ARRAY['HD video']::text[], ARRAY['Josefina Urraca, piano','Nathaniel Sullivan, baritone','Robert Sirvent, video Artist']::text[], ARRAY[]::text[], '[]'::jsonb, false),
  (1798, 'schumanop73', 'Fantasy Pieces for viola & piano Op.73', 'Robert Schumann composed the three Fantasiestucke, Op. 73, in just two days in February 1849, originally titling them "Soireestucke" (Evening Pieces) before settling on Fantasiestucke, a title he favored across several works. Scored for clarinet and piano, they carry Schumann''s own indication that the clarinet part may be played on viola or cello, and the viola-and-piano version is heard here. The three linked movements move from tender lyricism to increasing animation, played without pause and building in intensity toward an ardent close. Schumann (1810-1856), a central figure of German Romanticism, prized the fusion of poetry and music, and these miniatures distill his intimate, songful voice into one continuous arc of feeling.', 'vimeo', '709513259', '709513259', 'https://play.creartbox.nyc/wp-content/uploads/DSC05239.jpg', '11 min 25 sec', '04/09/2022', '', ARRAY['Robert Schumann']::text[], ARRAY['Piano','Viola']::text[], ARRAY['19th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Josefina Urraca, piano','Matthew Cohen, viola']::text[], ARRAY[]::text[], '[]'::jsonb, false),
  (1807, 'piano-quartet-in-a-minor-op-67', 'Piano quartet in a minor Op.67', 'Joaquin Turina completed his Piano Quartet in A minor, Op. 67, in 1931. Scored for violin, viola, cello and piano, it marries Andalusian color with the cyclic techniques Turina absorbed in Paris, where he studied at the Schola Cantorum and befriended Debussy, Ravel, Albeniz and Falla. Rather than opening with a large sonata movement, the quartet unfolds in a lento-vivo-andante sequence whose movements are bound together by recurring themes, a Franckian principle Turina made his own. Born in Seville in 1882, Turina was a pianist, critic and author who wove Spanish idioms into a cosmopolitan European craft, and this warmly lyrical, rhythmically vivid work counts among his finest chamber achievements.', 'vimeo', '713282481', '713282481', 'https://play.creartbox.nyc/wp-content/uploads/DSC05439.jpg', '17 min 38 sec', '04/10/2022', 'https://play.creartbox.nyc/title/piano-quartet-in-a-minor-op-67/', ARRAY['Joaquín Turina']::text[], ARRAY['Cello','Piano','Viola','Violin']::text[], ARRAY['20th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Josefina Urraca, piano','Mari Lee, violin','Matthew Cohen, viola','Yi Qun Xu, cello']::text[], ARRAY[]::text[], '[]'::jsonb, false),
  (2262, 'piano-trio-n-1', 'Piano Trio n. 1', 'Piano Trio No. 1 is a compact work for violin, cello and piano by the American composer Brittney Benton, written in 2024 and lasting roughly four and a half minutes. In it a recurring theme, first stated by the violin, is passed among all three instruments, finding its way into each section before the close. By the composer''s account it is her first piece for piano trio, one in which she steps away from her habitual tonal writing toward a freer language organized around a tonal center. Benton, based in New Haven, holds degrees from the University of Nevada, Las Vegas, and the Yale School of Music, and her music has been performed by ensembles including ZOFO and the Beo String Quartet.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/cc063d9a-1b4f-4dbb-ae81-2a52f28b47bd/playlist.m3u8', '', '', '', '', '', ARRAY['Brittney Benton']::text[], ARRAY[]::text[], ARRAY['21st Century']::text[], ARRAY['American']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '[]'::jsonb, false),
  (1486, 'quartet-for-the-end-of-time', 'Quartet for the End of Time', 'Olivier Messiaen composed the Quatuor pour la fin du temps in 1940-41 while a prisoner of war at Stalag VIII-A in Gorlitz, and it was first performed there in January 1941 for an audience of fellow prisoners, scored for the four instruments available to him: violin, clarinet, cello and piano. Inspired by the Book of Revelation and its angel who declares that there shall be time no longer, its eight movements range from the shimmering "Liturgie de cristal" to the radiant closing "Louange a l''Immortalite de Jesus." Messiaen (1908-1992), a devout Catholic, organist and pioneer of rhythm and birdsong, produced in these extraordinary circumstances one of the most visionary and enduring chamber works of the twentieth century.', 'youtube', '', '', 'https://play.creartbox.nyc/wp-content/uploads/ADS_0835.jpg', '53 min 52 sec', '08/31/2019', '', ARRAY['Olivier Messiaen']::text[], ARRAY['Cello','Clarinet','Piano','Violin']::text[], ARRAY['20th Century']::text[], ARRAY['European']::text[], ARRAY['Lossless audio']::text[], ARRAY['Jonathan Cohen, clarinet','Josefina Urraca, piano','Julia Yang, cello','Mari Lee, violin']::text[], ARRAY[]::text[], '[{"title":"I – Crystal liturgy","url":"https://creartbox-media-cdn.b-cdn.net/webimg/audios/20190830/01%20Crystal%20liturgy.mp3"},{"title":"II – Vocalise, for the Angel","url":"https://creartbox-media-cdn.b-cdn.net/webimg/audios/20190830/02%20Vocalise%2C%20for%20the%20Angel%20who%20announces%20the%20end%20of%20time.mp3"},{"title":"III – Abyss of birds","url":"https://creartbox-media-cdn.b-cdn.net/webimg/audios/20190830/03%20Abyss%20of%20birds.mp3"},{"title":"IV – Interlude","url":"https://creartbox-media-cdn.b-cdn.net/webimg/audios/20190830/04%20Interlude.mp3"},{"title":"V – Praise to the eternity of Jesus","url":"https://creartbox-media-cdn.b-cdn.net/webimg/audios/20190830/05%20Praise%20to%20the%20eternity%20of%20Jesus.mp3"},{"title":"VI – Dance of fury","url":"https://creartbox-media-cdn.b-cdn.net/webimg/audios/20190830/06%20Dance%20of%20fury%2C%20for%20the%20seven%20trumpets.mp3"},{"title":"VII – Tangle of rainbows","url":"https://creartbox-media-cdn.b-cdn.net/webimg/audios/20190830/07%20Tangle%20of%20rainbows%2C%20for%20the%20Angel%20who%20announces%20the%20end%20of%20time.mp3"},{"title":"VIII – Praise to the immortality of Jesus","url":"https://creartbox-media-cdn.b-cdn.net/webimg/audios/20190830/08%20Praise%20to%20the%20immortality%20of%20Jesus.mp3"}]'::jsonb, true),
  (1489, 'trio-for-flute-cello-and-piano', 'Trio for Flute, Cello and Piano', 'Ned Rorem composed his Trio for flute, cello and piano in 1960. One of the most distinctive voices in American music, Rorem (1923-2022) was equally renowned as a composer and as a diarist and essayist, and once remarked that in youth it was "a toss-up" whether he would become a composer or a writer, so he became a little of both. Best known as the pre-eminent American art-song composer of his generation, he brought that same lyric clarity to instrumental music. Cast in several movements, the Trio balances the flute''s airy line, the cello''s warmth and the piano''s coloristic support in music of transparent textures, elegant craft and unmistakably French-influenced sensibility.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/c6d2fbb7-814c-4e42-944c-5b27c52d1a2f/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/003.jpg', '5 min 14 sec', '03/01/2019', '', ARRAY['Ned Rorem']::text[], ARRAY['Cello','Flute','Piano']::text[], ARRAY['20th Century']::text[], ARRAY['American']::text[], ARRAY['HD video']::text[], ARRAY['Guillermo Laporta, flute','Josefina Urraca, piano','Julia Yang, cello']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (1560, 'three-nocturnes', 'Three Nocturnes', 'Ernest Bloch wrote his Three Nocturnes for piano trio in 1924, the year he became a naturalized American citizen, shortly before moving to San Francisco to head its Conservatory. Scored for violin, cello and piano, the set gathers three atmospheric character pieces: the first impressionistic, with exotic scales and ethereal sonorities; the second a lyrical, folk-tinged lullaby touched with canon; the third more restless, with the motoric drive of his early chamber music. A departure from Bloch''s overtly Hebraic idiom, the Nocturnes retain his characteristic mysticism and poetry. Bloch (1880-1959), born in Geneva and trained across Europe before emigrating to the United States in 1916, was a composer, conductor and influential teacher who bridged European Romanticism and American musical life.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/708189c6-fcce-4eab-a445-0b7e4f12ead9/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/004-3.jpg', '8 min 46 sec', '12/04/2021', '', ARRAY['Ernest Bloch']::text[], ARRAY['Cello','Piano','Violin']::text[], ARRAY['20th Century']::text[], ARRAY['American','European']::text[], ARRAY['HD video']::text[], ARRAY['Josefina Urraca, piano','Keir GoGwilt, violin','Yi Qun Xu, cello']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (1784, 'andante-con-moto-eg-116', 'Andante con moto EG 116', 'Edvard Grieg is celebrated above all for his orchestral works, songs and piano miniatures, but he twice attempted large-scale chamber music for piano trio. Around 1878 he began a trio and completed only a single movement, the Andante con moto in C minor for violin, cello and piano (EG 116). The manuscript surfaced after his death and was championed by his Dutch friend and colleague Julius Rontgen. A richly Romantic, songful movement, it opens with a brooding, lyrical theme and rises to passionate climaxes before subsiding, offering a tantalizing glimpse of the chamber symphony Grieg never finished. Grieg (1843-1907), Norway''s foremost composer, fused Germanic Romantic craft with the inflections of Norwegian folk music.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/3748aa40-9902-4e31-abef-7361df1beba3/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/008.jpg', '10 min 39 sec', '12/04/2021', '', ARRAY['Edvard Grieg']::text[], ARRAY['Cello','Piano','Violin']::text[], ARRAY['19th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Josefina Urraca, piano','Keir GoGwilt, violin','Yi Qun Xu, cello']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (1796, 'trio-in-e-flat-major-k-498', 'Trio in E flat Major K.498', 'Wolfgang Amadeus Mozart wrote this trio in Vienna, dating the manuscript 5 August 1786. Nicknamed the "Kegelstatt" Trio, it is scored for the unusual combination of clarinet, viola and piano. Mozart dedicated it to his pupil Franziska von Jacquin, whose family were close friends; they gave house concerts together, with her brother Nikolaus on flute and Franziska at the keyboard, and Mozart dedicated several works to the family. In three movements, the trio treats its three voices as equal partners, prizing intimate conversation over display, from the graceful opening Andante through a shadowed minuet to a spacious rondo finale. It stands among the earliest and most beloved works to feature the clarinet in chamber music. CreArtBox performs it here with flute in place of clarinet.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/d55e826c-4173-452b-bed7-4f47f3d99b0b/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/DSC05211-scaled.jpg', '18 min 36 sec', '04/09/2022', '', ARRAY['Mozart']::text[], ARRAY['Flute','Piano','Viola']::text[], ARRAY['18th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Guillermo Laporta, flute','Josefina Urraca, piano','Matthew Cohen, viola']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (1800, 'trio-op-18', 'Trio Op.18', 'Tatiana Nikolayeva (1924–1993) is best remembered as one of the great Soviet pianists—a celebrated Bach interpreter whose playing inspired Shostakovich''s 24 Preludes and Fugues—but she was also a prolific composer. Her Trio, Op. 18, scored for the unusual combination of flute, viola and piano, reveals this second creative life. Cast in several contrasting movements—among them a flowing Prelude, a quicksilver Scherzo and a searching, song-like Monologue—the work marries the lyricism and contrapuntal clarity of her Bach lineage with a warm, distinctly Russian expressive palette. The blend of flute brightness, viola warmth and piano resonance gives the Trio a chamber intimacy that has kept it a rewarding rarity in the repertoire.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/e6ae9bde-a67f-4dfa-af00-8fdf14ca5d84/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/DSC05267-scaled.jpg', '21 min 57 sec', '04/09/2022', '', ARRAY['Tatiana Nikolayeva']::text[], ARRAY['Flute','Piano','Viola']::text[], ARRAY['20th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Guillermo Laporta, flute','Josefina Urraca, piano','Matthew Cohen, viola']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (1802, 'we-can-learn-me-together', 'We Can Learn Me Together', 'American composer Bryan M. Wysocki wrote “We Can Learn Me Together” in 2019 for pianist Clare Longendyke and the violin–viola duo Sonic Apricity, for the Alba Music Festival''s composition program in Alba, Italy. The title comes from the closing line of a poem by the composer''s then-girlfriend, now wife, Jess Willis, written soon after the couple began dating—a candid reflection on the vulnerability of letting another person in. Wysocki translates that emotional openness into music of shared discovery, the instruments feeling their way toward one another and gradually learning to move as one. Heard here in a version for flute, viola and piano, it is an intimate, personal essay in trust and connection.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/ce34a5c8-942a-40e2-a9f8-d960eaafb8a1/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/DSC05348-scaled.jpg', '6 min 17 sec', '04/09/2022', '', ARRAY['Bryan M. Wysocki']::text[], ARRAY['Flute','Piano','Viola']::text[], ARRAY['21st Century']::text[], ARRAY['American']::text[], ARRAY['HD video']::text[], ARRAY['Guillermo Laporta, flute','Josefina Urraca, piano','Matthew Cohen, viola']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (1824, '3-pieces-for-cello-piano', '3 Pieces for Cello & Piano', 'Nadia Boulanger (1887–1979) is remembered above all as the twentieth century''s most influential teacher of composition—mentor to Copland, Piazzolla, Glass, Quincy Jones and countless others—yet she was a gifted composer in her own right before largely setting the pursuit aside. Her Trois Pièces for cello and piano, composed in 1914 and published the following year, began life as organ pieces that she transcribed for the duo. The three brief movements move from a dreamy, gently rocking Modéré in E-flat minor, through a folk-like central piece, to a lively, nervously rhythmic finale. Concise and beautifully crafted, they distill an unmistakably French sensibility—harmonic subtlety, restraint and quiet expressive depth—into barely eight minutes of music.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/ac520d65-806a-44ac-920b-5cf2fe24fea5/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/Part-3-Main-Edit-1.jpg', '3 min 32 sec', '', 'https://play.creartbox.nyc/title/3-pieces-for-cello-piano/', ARRAY['Nadia Boulanger']::text[], ARRAY['Cello','Piano']::text[], ARRAY['20th Century']::text[], ARRAY['European']::text[], ARRAY['4k video','HD video']::text[], ARRAY['Josefina Urraca, piano','Julia Yang, cello','Sarah K. Williams, visual Artist','visual artist']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (1828, 'piano-quintet-in-g-minor-op-49', 'Piano Quintet in G minor, Op. 49', 'Enrique Granados (1867–1916), the Catalan pianist-composer celebrated for the Spanish color of Goyescas and the Danzas españolas, composed his Piano Quintet in G minor, Op. 49, in the mid-1890s (sources give around 1895). An early chamber work pairing piano with string quartet, it unfolds with the grace and spontaneity that mark his style. The opening phrase, played in unison, immediately establishes the rhythmic character that runs through the piece; an atmosphere of passion and tension gives way to a more intense, expressive central section. Though Granados himself never regarded it as a major statement, the Quintet seduces with its lyrical charm and melodic generosity, offering an appealing glimpse of the composer before the fame of his mature Spanish masterpieces.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/925210c7-f30b-4a8a-b7e8-8f4d26c8150a/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/DSC00357-2.jpg', '17 min 14 sec', '09/27/2022', '', ARRAY['Enrique Granados']::text[], ARRAY['Cello','Dance','Flute','Piano','Viola','Violin']::text[], ARRAY['19th Century']::text[], ARRAY['European']::text[], ARRAY['4k video','HD video']::text[], ARRAY['Emilie Anne Gendron, violin','Guillermo Laporta, flute','Josefina Urraca, piano','Julia Yang, cello','Matthew Cohen, viola','Sarah K. Williams, visual Artist']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (1867, 'heart-meditation', 'Heart Meditation', '“Heart Meditation” is a work for ensemble and electronic track by Annamaria Kowalsky, a multidisciplinary composer and performer who blends classical training with contemporary and multimedia practice. Composed in 2021, the piece sets two time systems against each other: an internal pulse modeled on the heartbeat, and measured clock seconds. The musicians move intuitively through thirty-second time-frames, each finding their own path yet meeting at fixed anchor points where they must realign together. The result is an eleven-minute journey that oscillates between individual freedom and collective breath, inviting both players and listeners into a contemplative, almost bodily awareness of time. CreArtBox gave the work''s US premiere.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/67fbe759-5a8f-4ea0-8a1c-95d82741c0fb/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/056-scaled.jpg', '11 min 33 sec', '09/27/2022', '', ARRAY['Annamaria Kowalsky']::text[], ARRAY[]::text[], ARRAY['21st Century']::text[], ARRAY['European']::text[], ARRAY['4k video','HD video']::text[], ARRAY['Emilie Anne Gendron, violin','Guillermo Laporta, flute','Josefina Urraca, piano','Julia Yang, cello','Matthew Cohen, viola']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (1871, 'kakadu-variations-op-121a', 'Kakadu variations op. 121a', 'The “Kakadu” Variations is the nickname for Ludwig van Beethoven''s set of variations for piano trio on the popular tune “Ich bin der Schneider Kakadu” from a Singspiel by Wenzel Müller. Though Beethoven appears to have drafted the work around the turn of the nineteenth century, it was not published until 1824, as Opus 121a—the last of his piano trios to appear in print. Its most striking feature is the dramatic contrast between the long, brooding G-minor introduction—weightier and more searching than the material that follows—and the genial, light-hearted variations on Müller''s cheerful theme. Witty, virtuosic and full of character, the work shows Beethoven treating a simple popular melody with affectionate humor and inexhaustible invention.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/8449800a-22ca-4c32-9d01-6899707dc376/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/10.jpg', '24 min 22 sec', '01/26/2018', '', ARRAY['Ludwig van Beethoven']::text[], ARRAY['Cello','Piano','Violin']::text[], ARRAY['19th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Josefina Urraca, piano','Julia Yang, cello','Mélanie Clapiès, violin']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (1883, 'toccata-bruise', 'Toccata & bruise', '“toccata & bruise” (2016) is a duet for piano, pianist and fixed media by Celeste Oram, a composer who grew up in Aotearoa New Zealand and is now based in New York. The piece meditates on the physical idea of touch. As she plays, the pianist listens to Glenn Gould''s 1959 Salzburg recording of his own piano transcription of Sweelinck''s organ “Fantasia Contraria” in G Dorian; though the audience barely hears it, this recording serves as a hidden audio score to which the performer precisely synchronizes her gestures against fixed video. Oram frames the work as a “transcriptive fantasy”—a fantasia on touch itself, tracing how the organ''s mechanical action becomes, through Gould''s pianism, an intensely tactile art.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/64de021c-2d12-4318-b21b-7ee6851d53ee/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/085-scaled.jpg', '9 min 21 sec', '09/10/2022', '', ARRAY['Celeste Oram']::text[], ARRAY['Electronics','Piano']::text[], ARRAY['21st Century']::text[], ARRAY[]::text[], ARRAY['4k video']::text[], ARRAY['Josefina Urraca, piano']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (1935, 'sonata', 'Deuxième Sonate en trio', 'Claude Debussy composed his Sonata for flute, viola and harp in 1915—one of a projected set of six late sonatas for unusual instrumental combinations that his final illness left unfinished at three. Written in the shadow of the First World War, it is music of extraordinary refinement and elusive beauty, its three movements (Pastorale, Interlude and Finale) drifting between melancholy, playfulness and dance-like grace. The unusual pairing of flute, viola and harp yields a translucent, silvery sonority that helped redefine the possibilities of French chamber music. In CreArtBox''s version, piano takes the place of the harp, lending fresh color and resonance while preserving the score''s luminous, dreamlike character.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/64946dd5-307a-4ab6-9027-c02023c7cfd9/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/002-3.jpg', '', '', '', ARRAY['Claude Debussy']::text[], ARRAY['Flute','Piano','Viola']::text[], ARRAY['20th Century']::text[], ARRAY['European']::text[], ARRAY['HD video']::text[], ARRAY['Guillermo Laporta, flute','Josefina Urraca, piano','Matthew Cohen, viola']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (2008, 'vivaldi-la-notte', 'La Notte', '“La Notte” (“The Night”) is one of Antonio Vivaldi''s most atmospheric concertos—a rare programmatic flute concerto in G minor, RV 439, published in Amsterdam around 1728 as part of his Op. 10 set. Vivaldi (1678–1741), the Venetian “Red Priest” who did much to shape the solo concerto, evokes the unsettled world of night across its linked movements: shadowy opening gestures, a scurrying “Fantasmi” (ghosts), a restless dream, and a serene slow movement marked “Il Sonno” (sleep) before a brisk awakening. Here the concerto is heard in an intimate arrangement for flute, string trio and piano, bringing a fresh, chamber-scaled perspective to Vivaldi''s vivid nocturnal imagery.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/73ab8300-a9b0-403a-9c15-25e00fddfd55/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/circlenoirphoto2.jpg', '8 min 37 sec', '12/10/2023', '', ARRAY['Vivaldi']::text[], ARRAY['Cello','Flute','Piano','Viola','Violin']::text[], ARRAY['18th Century']::text[], ARRAY['European']::text[], ARRAY['4k video']::text[], ARRAY['Guillermo Laporta, flute','Harriet Langley, violin','Josefina Urraca, piano','Julia Yang, cello','Matthew Cohen, viola']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (2011, 'kaddish', 'Kaddish', 'Kaddish is the first of Maurice Ravel''s Deux mélodies hébraïques, composed in 1914 as settings of traditional Hebrew texts, paired with "L''énigme éternelle." The Kaddish is the ancient Aramaic prayer of mourning and praise, and Ravel treats its melismatic, cantorial line with the precision, elegance, and restrained emotional depth that mark all his music. Originally written for voice and piano and later orchestrated, it is heard here in an arrangement for cello and piano, the cello taking the vocal line''s long, ornamented phrases. Ravel, a towering figure of early twentieth-century French music, is celebrated for his crystalline orchestration and refined harmonic language, often linked to Impressionism yet always unmistakably his own.', 'youtube', 'JNTy18Ka61Y', 'JNTy18Ka61Y', 'https://play.creartbox.nyc/wp-content/uploads/kadish.jpg', '', '11/12/2023', '', ARRAY['Maurice Ravel']::text[], ARRAY['Cello','Piano']::text[], ARRAY['20th Century']::text[], ARRAY['European']::text[], ARRAY['4k video']::text[], ARRAY['Josefina Urraca, piano','Julia Yang, cello']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (2014, 'pictures-at-an-exhibition', 'Pictures at an Exhibition', 'Modest Mussorgsky composed Pictures at an Exhibition for solo piano in 1874, moved by the sudden death of his friend, the architect and painter Viktor Hartmann. Walking through a memorial exhibition of Hartmann''s work, Mussorgsky translated individual drawings and designs into musical "pictures"—from the lumbering ox-cart "Bydlo" to the fairy-tale hut of Baba Yaga and the towering "Great Gate of Kiev"—linked by a recurring "Promenade" that portrays the viewer strolling between them. Best known today in Maurice Ravel''s orchestration, the suite is heard here in an arrangement for flute, string trio, and piano. Mussorgsky, a leading member of Russia''s "Mighty Handful," had a gift for vivid pictorial writing and boldly original harmony that shaped later Russian music.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/b4dc09b9-0cfa-41a4-b6b8-101953bfaee5/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/pictures2.jpg', '36 min 15 sec', '11/14/2023', '', ARRAY['Modest Mussorgsky']::text[], ARRAY['Cello','Flute','Piano','Viola','Violin']::text[], ARRAY['19th Century']::text[], ARRAY['European']::text[], ARRAY['4k video']::text[], ARRAY['CreArtBox Ensemble','Emilie Anne Gendron, violin','Guillermo Laporta, flute','Josefina Urraca, piano','Julia Yang, cello','Matthew Cohen, viola']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (2026, 'chesapeake', 'Chesapeake', 'Chesapeake belongs to Pieces of Place, an ongoing series by composer, violist, and vocalist Hannah Selin for chamber ensemble with or without electronics that explores the meeting point of geology, ecology, and personal memory. Written in 2021, this movement evokes the northeastern shore of the Chesapeake Bay, where Selin spent childhood summers, layering superimposed timescales—geological, human, and tidal—into its texture; she has noted that rising seas may one day submerge the very peninsula on which it was conceived. Selin, based in New York, works across composition and performance, and her music often braids acoustic instruments with electronic sound. CreArtBox performs it here in its own chamber scoring.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/096b2a96-cb99-4581-92a8-50e5580b3688/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/004-4.jpg', '10 min 2 sec', '12/10/2023', '', ARRAY['Hannah Selin']::text[], ARRAY['Cello','Flute','Piano','Viola','Violin']::text[], ARRAY['21st Century']::text[], ARRAY['American']::text[], ARRAY['4k video']::text[], ARRAY['CreArtBox Ensemble','Guillermo Laporta, flute','Harriet Langley, violin','Josefina Urraca, piano','Julia Yang, cello','Matthew Cohen, viola','visual artist']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (2028, 'afilador', 'Afilador', 'Afilador (2022) by Spanish cellist-composer Andrea Casarrubios was commissioned by the Chicago Symphony Orchestra for its MusicNOW series and originally scored for clarinet, violin, viola, and cello. The title refers to the afilador, the itinerant knife-sharpener who once roamed Spanish streets announcing his trade on a small pan-flute; that whistle, steeped in childhood nostalgia, becomes a central musical gesture of the piece. In this version, adapted by the composer for CreArtBox, the flute returns to evoke the sharpener''s call, joining the string trio. Casarrubios, born in Madrid and now based in New York, is a cellist and composer whose music grows out of the human experience and has been widely performed and recorded.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/d6914ec2-693c-4013-805e-356129f0375c/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/002.jpg', '10 min 2 sec', '11/14/2023', '', ARRAY['Andrea Casarrubios']::text[], ARRAY['Cello','Flute','Viola','Violin']::text[], ARRAY['21st Century']::text[], ARRAY['European']::text[], ARRAY['4k video']::text[], ARRAY['Emilie Anne Gendron, violin','Guillermo Laporta, flute','Julia Yang, cello','Matthew Cohen, viola']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (2046, 'thousandth-orange', 'Thousandth Orange', 'The Thousandth Orange (2018) is a piano quartet—violin, viola, cello, and piano—by American composer Caroline Shaw, the Pulitzer Prize-winning writer, violinist, and singer. Co-commissioned by the Britten Sinfonia and Wigmore Hall, it grew out of Shaw''s love of Brahms''s piano quartets and her fascination with still-life paintings of fruit. Beginning from a simple four-chord progression, the piece meditates on the small, oblique revelations that time can open up within a musical memory; its title conjures a thousand shades of orange, or a thousand ways of looking at a single one. Rhythmically intricate and rich in color and texture, it is heard here in a live CreArtBox performance at the DiMenna Center.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/fd38ec57-081a-4b2c-8bb7-d124b1496169/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/495392654_1316810157117922_6079046438971270533_n.jpg', '11 min 38 sec', '02/11/2025', 'https://play.creartbox.nyc/title/thousandth-orange/', ARRAY['Caroline Shaw']::text[], ARRAY['Cello','Piano','Viola','Violin']::text[], ARRAY['21st Century']::text[], ARRAY['American']::text[], ARRAY['24bits audio','4k video']::text[], ARRAY['Emilie Anne Gendron, violin','Josefina Urraca, piano','Julia Yang, cello','Matthew Cohen, viola']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (2221, 'american-quartet', 'American Quartet', 'Antonin Dvorak composed his String Quartet No. 12 in F major, Op. 96—the "American"—in 1893 during a restful summer among the Czech-speaking community of Spillville, Iowa, where the Bohemian composer vacationed while directing the National Conservatory in New York. Sketched in only a few days and completed within weeks, it radiates open-air lyricism and the pentatonic, folk-inflected melody of his American period, from its sunny opening to the whirling finale. It remains one of the best-loved works in the entire quartet repertoire. Dvorak, one of the great nineteenth-century Czech composers, drew on Bohemian and American idioms alike. CreArtBox performs it here in an arrangement featuring flute in place of a violin.', 'none', '', '', 'https://play.creartbox.nyc/wp-content/uploads/IMG_3176-scaled.png', '26 min 52 sec', '05/29/2025', '', ARRAY['Antonín Dvořák']::text[], ARRAY['Cello','Flute','Viola','Violin']::text[], ARRAY['19th Century']::text[], ARRAY['European']::text[], ARRAY['Lossless audio']::text[], ARRAY['Emilie Anne Gendron, violin','Guillermo Laporta, flute','Julia Yang, cello','Matthew Cohen, viola']::text[], ARRAY[]::text[], '[{"title":"Dvorak – String Quartet No.12 \r\n    I. Allegro ma non troppo","url":"https://creartbox-media-cdn.b-cdn.net/webimg/projects_photos/20241211/audio/07DvorakI.mp3"},{"title":"Dvorak – String Quartet No.12 \r\n    II. Lento","url":"https://creartbox-media-cdn.b-cdn.net/webimg/projects_photos/20241211/audio/08DvorakII.mp3"},{"title":"Dvorak – String Quartet No.12 \r\n    III. Molto vivace — Trio","url":"https://creartbox-media-cdn.b-cdn.net/webimg/projects_photos/20241211/audio/09DvorakIII.mp3"},{"title":"Dvorak – String Quartet No.12 \r\n    IV. Finale. Vivace ma non troppo","url":"https://creartbox-media-cdn.b-cdn.net/webimg/projects_photos/20241211/audio/10DvorakIV.mp3"}]'::jsonb, true),
  (2225, 'piano-quartet-no-3-op-60', 'Piano Quartet No. 3 in C minor, Op. 60 (III. Andante)', 'Despite its slug, this entry''s metadata identifies it as Johannes Brahms''s Piano Quartet No. 3 in C minor, Op. 60—specifically the third movement, Andante. Brahms labored over the quartet across two decades, beginning it around 1855 amid personal turmoil and completing it only in 1875. The Andante, in E major, is among his most songful slow movements: the cello introduces a broad, aching melody that the piano and upper strings take up in warm dialogue, balancing lyrical tenderness with Brahms''s characteristic structural rigor. Scored for piano, violin, viola, and cello, it is presented here by CreArtBox. Brahms, a titan of nineteenth-century German music, brought Classical discipline to Romantic expression across his symphonies, concertos, and chamber works.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/62d677e1-e80a-4bdf-bd3c-3973893802e1/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/04.jpg', '9 min 30 sec', '02/11/2025', '', ARRAY['Johannes Brahms']::text[], ARRAY['Cello','Piano','Viola','Violin']::text[], ARRAY['19th Century']::text[], ARRAY['European']::text[], ARRAY['24bits audio','4k video']::text[], ARRAY['Emilie Anne Gendron, violin','Josefina Urraca, piano','Julia Yang, cello','Matthew Cohen, viola']::text[], ARRAY[]::text[], '[]'::jsonb, true),
  (2256, 'musica-ricercata', 'Musica Ricercata', 'Gyorgy Ligeti''s Musica ricercata (1951–53) is one of the Hungarian composer''s boldest early works, written for solo piano in eleven movements. Ligeti took the idea of the ricercar—a "searching out"—literally: the first movement uses only a single pitch and its octaves, and each successive movement adds one more note, so the music expands from stark austerity toward an increasingly rich harmonic world before culminating in a chromatic finale. Composed in Communist Hungary, parts of it fell foul of the authorities and went unperformed for years. Heard here in an arrangement by Guillermo Laporta for CreArtBox, the cycle becomes a gradual, exhilarating exploration of musical possibility. Ligeti went on to become one of the most inventive and influential composers of the twentieth century.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/4214c16c-1c0a-4bdc-b4de-6b93bf95246e/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/MG_0161.jpg', '14 min 32 sec', '12/12/2025', 'https://play.creartbox.nyc/title/musica-ricercata/', ARRAY['György Ligeti']::text[], ARRAY['Cello','Flute','Piano','Viola','Violin']::text[], ARRAY['20th Century']::text[], ARRAY['European']::text[], ARRAY['24bits audio','4k video']::text[], ARRAY['Emilie Anne Gendron, violin','Guillermo Laporta, flute','Josefina Urraca, piano','Julia Yang, cello','Matthew Cohen, viola']::text[], ARRAY[]::text[], '[{"title":"I. Allegro con spirito","url":"https://creartbox-media-cdn.b-cdn.net/webimg/projects_photos/20251212/audio/02%20ligeti%2001%20(audio).mp3"},{"title":"II. Rubato lamentoso","url":"https://creartbox-media-cdn.b-cdn.net/webimg/projects_photos/20251212/audio/02%20ligeti%2002%20(audio).mp3"},{"title":"III. Allegro grazioso","url":"https://creartbox-media-cdn.b-cdn.net/webimg/projects_photos/20251212/audio/02%20ligeti%2003%20(audio).mp3"},{"title":"IV. Presto ruvido","url":"https://creartbox-media-cdn.b-cdn.net/webimg/projects_photos/20251212/audio/02%20ligeti%2004%20(audio).mp3"},{"title":"V. Adagio mesto. Béla Bartók in memoriam","url":"https://creartbox-media-cdn.b-cdn.net/webimg/projects_photos/20251212/audio/02%20ligeti%2005%20(audio).mp3"},{"title":"VI. Molto vivace, capriccioso","url":"https://creartbox-media-cdn.b-cdn.net/webimg/projects_photos/20251212/audio/02%20ligeti%2006%20(audio).mp3"}]'::jsonb, true),
  (2260, 'twilight-at-dawn', 'Twilight at Dawn', 'Twilight at Dawn (2024) is a chamber work by American composer Devin Cholodenko, whose music explores the role of tonality in the twenty-first century. The piece lingers in the fragile threshold between night and day, when light first breaks through darkness—music of hesitant, searching, luminous gestures that invites the listener to dwell in the mystery of beginnings. Originally conceived for string quartet, it is heard here in a version for flute quartet—flute, violin, viola, and cello—performed by CreArtBox. Cholodenko''s works have been taken up by a range of chamber ensembles across the United States.', 'hls', 'https://vz-a6a9f576-8c5.b-cdn.net/34b94837-4267-4e67-b6df-fb50ea4c55e1/playlist.m3u8', '', 'https://play.creartbox.nyc/wp-content/uploads/DSC0028-scaled.jpg', '5 min 54 sec', '10/17/2025', '', ARRAY['Devin Cholodenko']::text[], ARRAY['Cello','Flute','Viola','Violin']::text[], ARRAY['21st Century']::text[], ARRAY['American']::text[], ARRAY['24bits audio','4k video','Lossless audio']::text[], ARRAY['Guillermo Laporta, flute','Julia Yang, cello','Matthew Cohen, viola']::text[], ARRAY[]::text[], '[]'::jsonb, true)
